--------------------------------------------------------
--  DDL for Trigger TRG_SECTIONS_AUTO_ID
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "CAMPUS_ADMIN"."TRG_SECTIONS_AUTO_ID" 
BEFORE INSERT ON "CAMPUS_ADMIN"."SECTIONS"
FOR EACH ROW
BEGIN
  -- If the backend doesn't provide an ID, we generate one smartly!
  IF :NEW.SECTION_ID IS NULL THEN
    :NEW.SECTION_ID := 'SEC-' || TO_CHAR("CAMPUS_ADMIN"."SECTION_SEQ".NEXTVAL, 'FM000');
  END IF;
END;

/
ALTER TRIGGER "CAMPUS_ADMIN"."TRG_SECTIONS_AUTO_ID" ENABLE;
